import { test } from 'node:test';
import assert from 'node:assert/strict';
import { getTableConfig, PgTable } from 'drizzle-orm/pg-core';
import * as authSchema from '../../db/auth-schema.ts';

// Better Auth 1.7.5 with github, deviceAuthorization, @better-auth/api-key, jwt, @better-auth/mcp (+ oauth-provider),
// @better-auth/cimd (no tables) and organization, as generated by `npm run auth:schema`.
const AUTH_TABLES = [
  'account', 'apikey', 'device_code', 'invitation', 'jwks', 'member', 'oauth_access_token', 'oauth_client',
  'oauth_client_assertion', 'oauth_client_resource', 'oauth_consent', 'oauth_refresh_token', 'oauth_resource',
  'organization', 'session', 'user', 'verification',
];

test('every Better Auth table for the spec plugin set exists, and all of them live in schema auth', () => {
  const tables = Object.values(authSchema).filter((t) => t instanceof PgTable).map((t) => getTableConfig(t));
  assert.deepEqual(tables.map((c) => c.name).sort(), AUTH_TABLES);
  assert.deepEqual([...new Set(tables.map((c) => c.schema))], ['auth']);
});

test('db/auth-schema.ts is the generated file, not hand-edited', async () => {
  const { readFile } = await import('node:fs/promises');
  const src = await readFile(new URL('../../db/auth-schema.ts', import.meta.url), 'utf8');
  assert.match(src, /^\/\/ Generated by `npm run auth:schema`/);
  assert.doesNotMatch(src, /\bpgTable\(/);
});
